const frpi = (p, q) => { if (q < 0) { p = -p; q = -q; } const g = pgcd(p, q); p /= g; q /= g; if (!p) return '0'; const a = Math.abs(p), s = p < 0 ? '-' : ''; return q === 1 ? s + (a === 1 ? '' : a) + '\\pi' : s + '\\dfrac{' + (a === 1 ? '' : a) + '\\pi}{' + q + '}'; };
