// Candidats de réponses fausses écartés quand ils ne sont pas des probabilités plausibles (hors de ]0 ; 1[).
const frP = (n, d) => n > 0 && n < d ? fr(n, d) : null, d10P = n => n > 0 && n < 10 ? d10(n) : null, d100P = n => n > 0 && n < 100 ? d100(n) : null, sans = L => L.filter(x => x !== null && x !== undefined);

// --- A. Thèmes étoffés ---
const carresN = () => { const n = R(11, 31), d = n % 10, z = n - d, c = n * n; return Q(`Calculez ${K(n + '^2')}.`, c, melanger([c + 10, c - 10, c + 20, c - 20, c + n, c - n]), d ? `On décompose ${K(n + ' = ' + z + '+' + d)} et l'on applique ${K('(a+b)^2 = a^2+2ab+b^2')} : ${K(z * z + '+' + 2 * z * d + '+' + d * d + ' = ' + c)}.` : `${K(n + '^2 = ' + z / 10 + '^2 \\times 10^2 = ' + c)}.`); };
const cubesN = () => { const n = R(2, 10), c = n ** 3; return Q(`Calculez ${K(n + '^3')}.`, c, melanger([3 * n, n * n, c + n, c - n, c + n * n, 3 * n * n]), `${K(n + '^3 = ' + n + ' \\times ' + n + ' \\times ' + n + ' = ' + n * n + ' \\times ' + n + ' = ' + c)}.`); };
