const sEntiers = (L = [10, 20, 30, 40, 50, 60, 100, 200]) => { const n = pick(L), s = n * (n + 1) / 2; return Q(`Calculez ${K('1 + 2 + 3 + \\dots + ' + n)}.`, s, [n * n, n * (n - 1) / 2, n * (n + 1), n * n / 2], `${K('1 + 2 + \\dots + n = \\dfrac{n(n+1)}{2}')} : ici ${K('\\dfrac{' + n + ' \\times ' + (n + 1) + '}{2} = ' + s)}.`); };
const sGeo = () => { const q = pick([2, 2, 3]), n = q === 2 ? R(4, 9) : R(3, 4), N = q ** (n + 1), s = (N - 1) / (q - 1), T = q === 2 ? '1 + 2 + 4 + \\dots + 2^{' + n + '}' : Array.from({ length: n + 1 }, (_, i) => 3 ** i).join(' + ');
  return Q(`Calculez ${K(T)}.`, s, [N, N - 1, (q ** n - 1) / (q - 1), s + 1, q ** n], `Somme des termes d'une suite géométrique de raison ${K(q)}, de ${K(q + '^0')} à ${K(q + '^{' + n + '}')} : ${K('1 + q + \\dots + q^{n} = \\dfrac{q^{n+1} - 1}{q - 1}')}, soit ${K(q === 2 ? '2^{' + (n + 1) + '} - 1 = ' + s : '\\dfrac{3^{' + (n + 1) + '} - 1}{2} = \\dfrac{' + (N - 1) + '}{2} = ' + s)}.`); };
const sDemi = () => { const n = R(3, 6), D = 2 ** n; return Q(`Calculez ${K('1 + \\dfrac12 + \\dfrac14 + \\dots + \\dfrac{1}{' + D + '}')}.`, fr(2 * D - 1, D), ['2', fr(D - 1, D), fr(2 * D + 1, D), fr(2 * D - 1, 2 * D)], `Somme des termes d'une suite géométrique de raison ${K('\\dfrac12')}, de ${K('\\left(\\dfrac12\\right)^0')} à ${K('\\left(\\dfrac12\\right)^{' + n + '}')} : ${K('\\dfrac{1 - \\left(\\frac12\\right)^{' + (n + 1) + '}}{1 - \\frac12} = 2 - \\dfrac{1}{' + D + '} = ' + fr(2 * D - 1, D))}.`); };
const sBloc = () => { const a = pick([5, 10, 11, 20, 21, 50, 51]), m = pick([10, 11, 20, 21]), b = a + m - 1, s = m * (a + b) / 2; return Q(`Calculez ${K(a + ' + ' + (a + 1) + ' + ' + (a + 2) + ' + \\dots + ' + b)}.`, s, [m * (a + b), s - a, s + b, s + m], `La somme de termes consécutifs d'une suite arithmétique vaut le nombre de termes multiplié par la moyenne du premier et du dernier. Il y a ${K(b + ' - ' + a + ' + 1 = ' + m)} termes : ${K(m + ' \\times \\dfrac{' + a + ' + ' + b + '}{2} = ' + s)}.`); };
